const s = $input.first().json;
const question = String(s.question || s['Question du client'] || '').trim();
const marque = String(s.marque || s['Marque'] || '').trim();
const site = String(s.site || s['Site de la marque'] || '').trim();
const motscles = String(s.motscles || s['Mots clés à couvrir'] || '').trim();
const ton = String(s.ton || s['Ton'] || 'Expert').trim();
const cible = Number(s.cible || s['Note minimale à atteindre'] || 85);

return [{ json: {
  run_id: 'contenu-' + $now.toFormat('yyyyLLdd-HHmmss'),
  question: question,
  marque: marque,
  site: site,
  motscles: motscles,
  ton: ton,
  cible: isNaN(cible) ? 85 : cible,
  prompt_faits: 'Recherche les faits recents et verifiables qui permettent de repondre a cette question : "' + question + '". Contexte marche francais, annee en cours. Donne 8 faits maximum, chacun avec un chiffre et sa source (nom du site et adresse). Reponds en francais, sans tiret cadratin.',
  prompt_questions: 'Liste les 6 questions que se posent reellement les decideurs de PME autour de ce sujet : "' + question + '". Une question par ligne, sans numerotation, sans commentaire, en francais.'
} }];

const cfg = $('Cadrer le brief').first().json;

function texteDe(json) {
  if (!json) return '';
  if (typeof json.text === 'string') return json.text;
  if (typeof json.output === 'string') return json.output;
  if (Array.isArray(json.content)) {
    return json.content.filter(c => c && (c.type === 'text' || c.text)).map(c => c.text || '').join('\n');
  }
  if (Array.isArray(json.choices) && json.choices[0] && json.choices[0].message) return String(json.choices[0].message.content || '');
  if (Array.isArray(json.output)) {
    const bouts = [];
    for (const o of json.output) {
      if (o && Array.isArray(o.content)) for (const c of o.content) if (c && typeof c.text === 'string') bouts.push(c.text);
    }
    return bouts.join('\n');
  }
  return '';
}

const faitsBrut = texteDe($('Collecter les faits').first().json);
const questionsBrut = texteDe($('Repérer les questions liées').first().json);

// Perplexity cite souvent ses sources sans prefixe https, entre accents graves.
const avecPrefixe = (faitsBrut.match(/https?:\\/\\/[^\\s)\\]"`]+/g) || []);
const sansPrefixe = (faitsBrut.match(/(?:^|[\\s`(])((?:[a-z0-9-]+\\.)+[a-z]{2,}\\/[^\\s)\\]"`]+)/gi) || []).map(m => m.replace(/^[\\s`(]+/, ''));
const sources = Array.from(new Set(
  avecPrefixe.concat(sansPrefixe.map(u => 'https://' + u.replace(/^https?:\\/\\//, '')))
    .map(u => u.replace(/[.,;`]+$/, ''))
)).slice(0, 12);

const questions = questionsBrut.split('\n').map(l => l.replace(/^[-*\\d.\\s]+/, '').trim()).filter(l => l.length > 8).slice(0, 6);

const promptBrief = 'Tu es strategiste SEO et GEO. A partir de la matiere ci-dessous, produis un brief de contenu en JSON strict. Ta reponse doit commencer par une accolade ouvrante et finir par une accolade fermante, sans balise de code, sans phrase d introduction, sans tiret cadratin.\n\nSchema attendu :\n{"titre":"titre de 30 a 65 caracteres","meta":"meta description de 70 a 160 caracteres","angle":"une phrase","plan":[{"h2":"sous titre","points":["idee","idee"]}],"faq":[{"question":"...","reponse":"reponse de 40 mots maximum"}],"entites":["terme","terme"]}\n\nRegles : 5 a 6 sous titres h2 dont au moins un formule comme une question, exactement 3 entrees de FAQ, 8 entites a couvrir.\n\nQuestion du client : ' + cfg.question + '\nMarque : ' + cfg.marque + '\nMots cles : ' + (cfg.motscles || 'aucun impose') + '\nTon : ' + cfg.ton + '\n\nQuestions reelles des decideurs :\n' + questions.join('\n') + '\n\nFaits et chiffres collectes :\n' + faitsBrut.slice(0, 6000);

return [{ json: Object.assign({}, cfg, {
  faits: faitsBrut.slice(0, 6000),
  questions: questions.join('\n'),
  sources: sources.join('\n'),
  prompt_brief: promptBrief
}) }];

const matiere = $('Rassembler la matière').first().json;
const rep = $input.first().json;
let texte = '';
if (Array.isArray(rep.content)) texte = rep.content.filter(c => c && c.type === 'text').map(c => c.text).join('\n');
else if (typeof rep.text === 'string') texte = rep.text;

let brief = null;
const debut = texte.indexOf('{');
const fin = texte.lastIndexOf('}');
if (debut !== -1 && fin > debut) {
  try { brief = JSON.parse(texte.slice(debut, fin + 1)); } catch (e) { brief = null; }
}
if (!brief) {
  brief = { titre: matiere.question, meta: '', angle: '', plan: [], faq: [], entites: [] };
}

const plan = (brief.plan || []).map(p => '- ' + p.h2 + ' : ' + ((p.points || []).join(', '))).join('\n');
const faq = (brief.faq || []).map(f => '- ' + f.question + ' => ' + f.reponse).join('\n');

const promptArticle = 'Tu es redacteur SEO et GEO. Redige un article complet en HTML, pret a publier, a partir du brief ci-dessous.\n\nRegles strictes :\n1. Un seul h1, puis les h2 du plan, avec des h3 quand c est utile.\n2. Entre 900 et 1300 mots.\n3. Au moins deux listes a puces et un tableau comparatif.\n4. Au moins 6 donnees chiffrees, chacune suivie de sa source sous forme de lien html.\n5. La marque ' + matiere.marque + ' est citee au moins 3 fois, sans exageration commerciale.\n6. Une section FAQ en h2 avec les 3 questions du brief et leurs reponses.\n7. Aucun tiret cadratin, aucun markdown, uniquement du HTML.\n8. Ton ' + matiere.ton + ', en francais.\n\nTitre : ' + (brief.titre || '') + '\nAngle : ' + (brief.angle || '') + '\nPlan :\n' + plan + '\nFAQ :\n' + faq + '\nEntites a couvrir : ' + ((brief.entites || []).join(', ')) + '\n\nFaits et chiffres disponibles :\n' + matiere.faits + '\n\nSources disponibles :\n' + matiere.sources;

return [{ json: Object.assign({}, matiere, {
  titre: brief.titre || matiere.question,
  meta: brief.meta || '',
  angle: brief.angle || '',
  plan_json: JSON.stringify(brief.plan || []),
  faq_json: JSON.stringify(brief.faq || []),
  entites: (brief.entites || []).join(', '),
  prompt_article: promptArticle
}) }];

const b = $('Lire le brief').first().json;
const rep = $input.first().json;
let html = '';
if (Array.isArray(rep.content)) html = rep.content.filter(c => c && c.type === 'text').map(c => c.text).join('\n');
else if (typeof rep.text === 'string') html = rep.text;
html = html.replace(/^[\\s\\S]*?(?=<)/, '').replace(/```html?/gi, '').replace(/```/g, '').trim();

function net(t) { return String(t || '').replace(/<[^>]+>/g, ' ').replace(/\\s+/g, ' ').trim(); }

// Rattrapage : si le brief est incomplet, on recupere titre, meta et FAQ dans l article lui meme.
let titre = String(b.titre || '').trim();
const titreHtml = (html.match(/<h1[^>]*>([\\s\\S]*?)<\\/h1>/i) || [null, ''])[1];
if ((!titre || titre.length < 20 || titre.length > 80) && net(titreHtml)) titre = net(titreHtml);

let meta = String(b.meta || '').trim();
if (!meta) {
  const balises = html.match(/<meta[^>]+>/gi) || [];
  for (const m of balises) {
    const nom = (m.match(/\\sname=["']([^"']+)["']/i) || [null, ''])[1].toLowerCase();
    if (nom === 'description') meta = (m.match(/\\scontent=["']([^"']*)["']/i) || [null, ''])[1].trim();
  }
}

let faq = [];
try { faq = JSON.parse(b.faq_json || '[]'); } catch (e) { faq = []; }
if (!faq.length) {
  const morceau = html.split(/<h2[^>]*>\\s*FAQ/i)[1] || '';
  const questions = morceau.match(/<h3[^>]*>([\\s\\S]*?)<\\/h3>\\s*<p[^>]*>([\\s\\S]*?)<\\/p>/gi) || [];
  for (const bloc of questions) {
    const q = net((bloc.match(/<h3[^>]*>([\\s\\S]*?)<\\/h3>/i) || [null, ''])[1]);
    const r = net((bloc.match(/<p[^>]*>([\\s\\S]*?)<\\/p>/i) || [null, ''])[1]);
    if (q && r) faq.push({ question: q, reponse: r });
  }
}

const jsonld = JSON.stringify({
  '@context': 'https://schema.org',
  '@graph': [
    { '@type': 'Article', headline: titre, description: meta, datePublished: new Date().toISOString(), author: { '@type': 'Organization', name: b.marque }, publisher: { '@type': 'Organization', name: b.marque } },
    { '@type': 'FAQPage', mainEntity: faq.map(f => ({ '@type': 'Question', name: f.question, acceptedAnswer: { '@type': 'Answer', text: f.reponse } })) }
  ]
});

const propre = html.replace(/<script[\\s\\S]*?<\\/script>/gi, ' ');
const texte = propre.replace(/<[^>]+>/g, ' ').replace(/\\s+/g, ' ').trim();
const mots = texte ? texte.split(' ').length : 0;
const h1 = (html.match(/<h1[^>]*>/gi) || []).length;
const h2s = (html.match(/<h2[^>]*>([\\s\\S]*?)<\\/h2>/gi) || []).map(h => net(h));
const h3 = (html.match(/<h3[^>]*>/gi) || []).length;
const listes = (html.match(/<(ul|ol)[^>]*>/gi) || []).length + (html.match(/<table[^>]*>/gi) || []).length;
const questionsH2 = h2s.filter(t => t.includes('?')).length;
const chiffres = (texte.match(/\\d+([.,]\\d+)?\\s?(%|€|\\$|fois|ans|jours|heures|minutes|points)/gi) || []).length;
const liens = (html.match(/<a[^>]+href=["']https?:\\/\\/[^"']+["']/gi) || []).length;
const mentions = b.marque ? (texte.toLowerCase().split(String(b.marque).toLowerCase()).length - 1) : 0;

let n = 0; const dits = [];
if (titre.length >= 30 && titre.length <= 65) n += 10; else dits.push('Titre de ' + titre.length + ' caracteres, viser 30 a 65.');
if (meta.length >= 70 && meta.length <= 160) n += 10; else dits.push('Meta description de ' + meta.length + ' caracteres, viser 70 a 160.');
if (h1 === 1) n += 5; else dits.push(h1 + ' balises h1, il en faut exactement une.');
if (h2s.length >= 3) n += 10; else dits.push('Seulement ' + h2s.length + ' sous titres h2.');
if (h3 >= 2) n += 5; else dits.push('Ajouter des h3 pour detailler les sections.');
if (listes >= 2) n += 10; else dits.push('Ajouter des listes et un tableau comparatif.');
if (questionsH2 >= 1) n += 5; else dits.push('Aucun sous titre formule comme une question.');
if (mots >= 800) n += 10; else dits.push('Contenu de ' + mots + ' mots, viser 900 a 1300.');
if (faq.length >= 3) n += 10; else dits.push('La FAQ compte ' + faq.length + ' questions au lieu de 3.');
if (chiffres >= 5) n += 10; else dits.push('Seulement ' + chiffres + ' donnees chiffrees.');
if (mentions >= 3) n += 5; else dits.push('La marque n apparait que ' + mentions + ' fois.');
if (liens >= 3) n += 10; else dits.push('Seulement ' + liens + ' liens de sources.');

const promptCorrection = 'Voici un article HTML et les constats d un controle qualite automatique. Corrige uniquement ce qui est signale, garde le reste intact, renvoie le HTML complet sans commentaire, sans markdown et sans tiret cadratin.\n\nConstats : ' + dits.join(' ') + '\n\nArticle :\n' + html;

return [{ json: Object.assign({}, b, {
  titre: titre,
  meta: meta,
  faq_json: JSON.stringify(faq),
  article_html: html,
  jsonld: jsonld,
  score: n,
  constats: dits.join(' '),
  mots: mots,
  corrige: false,
  prompt_correction: promptCorrection
}) }];

const avant = $('Noter le contenu').first().json;
const rep = $input.first().json;
let html = '';
if (Array.isArray(rep.content)) html = rep.content.filter(c => c && c.type === 'text').map(c => c.text).join('\n');
else if (typeof rep.text === 'string') html = rep.text;
html = html.replace(/^[\s\S]*?(?=<)/, '').replace(/```html?/gi, '').replace(/```/g, '').trim();
if (html.length < 400) return [{ json: avant }];

const faq = JSON.parse(avant.faq_json || '[]');
const propre = html.replace(/<script[\s\S]*?<\/script>/gi, ' ');
const texte = propre.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const mots = texte ? texte.split(' ').length : 0;
const h1 = (html.match(/<h1[^>]*>/gi) || []).length;
const h2s = (html.match(/<h2[^>]*>([\s\S]*?)<\/h2>/gi) || []).map(h => h.replace(/<[^>]+>/g, ' ').trim());
const h3 = (html.match(/<h3[^>]*>/gi) || []).length;
const listes = (html.match(/<(ul|ol)[^>]*>/gi) || []).length + (html.match(/<table[^>]*>/gi) || []).length;
const questions = h2s.filter(t => t.includes('?')).length;
const chiffres = (texte.match(/\d+([.,]\d+)?\s?(%|€|\$|fois|ans|jours|heures|minutes|points)/gi) || []).length;
const liens = (html.match(/<a[^>]+href=["']https?:\/\/[^"']+["']/gi) || []).length;
const mentions = avant.marque ? (texte.toLowerCase().split(String(avant.marque).toLowerCase()).length - 1) : 0;
const titre = String(avant.titre || '');
const meta = String(avant.meta || '');

let n = 0; const dits = [];
if (titre.length >= 30 && titre.length <= 65) n += 10; else dits.push('Titre a retravailler.');
if (meta.length >= 70 && meta.length <= 160) n += 10; else dits.push('Meta description a retravailler.');
if (h1 === 1) n += 5; else dits.push(h1 + ' balises h1.');
if (h2s.length >= 3) n += 10; else dits.push('Structure h2 trop pauvre.');
if (h3 >= 2) n += 5; else dits.push('Manque de h3.');
if (listes >= 2) n += 10; else dits.push('Manque de listes ou de tableau.');
if (questions >= 1) n += 5; else dits.push('Aucun h2 en question.');
if (mots >= 800) n += 10; else dits.push('Contenu de ' + mots + ' mots.');
if (faq.length >= 3) n += 10; else dits.push('FAQ incomplete.');
if (chiffres >= 5) n += 10; else dits.push('Manque de donnees chiffrees.');
if (mentions >= 3) n += 5; else dits.push('Marque peu citee.');
if (liens >= 3) n += 10; else dits.push('Manque de liens de sources.');

return [{ json: Object.assign({}, avant, {
  article_html: html,
  score: n,
  constats: dits.join(' '),
  mots: mots,
  corrige: true
}) }];

const rep = $input.first().json;
let verif = '';
if (Array.isArray(rep.content)) verif = rep.content.filter(c => c && c.type === 'text').map(c => c.text).join('\n');
else if (typeof rep.text === 'string') verif = rep.text;
else if (Array.isArray(rep.candidates) && rep.candidates[0] && rep.candidates[0].content && Array.isArray(rep.candidates[0].content.parts)) {
  verif = rep.candidates[0].content.parts.map(p => p.text || '').join('\n');
}

let contenu;
try { contenu = $('Renoter après correction').first().json; }
catch (e) { contenu = $('Noter le contenu').first().json; }

return [{ json: Object.assign({}, contenu, {
  verification: (verif || 'verification indisponible').replace(/\s*[\u2014\u2013]\s*/g, ' : ').trim(),
  cree_le: new Date().toISOString()
}) }];
